#include <iostream>
#include <array>
#include <span>
int countPositive(std::span<const int> values) {
    int count{};
    for (int value : values) { if (value > 0) { ++count; } }
    return count;
}
int main() {
    std::array<int, 3> values{-2, 0, 4};
    bool pass = countPositive(values) == 1;
    std::cout << (pass ? "PASS\n" : "FAIL\n");
    return pass ? 0 : 1;
}

